describe('Product Detail Page Navigation', () => {
  it('should navigate to the product detail page', () => {
    cy.visit('https://www.saucedemo.com');
    cy.get('a[data-test="inventory_item_name"]').click();
    cy.url().should('include', '/inventory-item.html');
  });

  it('should return to the product catalogue', () => {
    cy.visit('https://www.saucedemo.com');
    cy.get('a[data-test="inventory_item_name"]').click();
    cy.get('a[data-test="back-to-products"]').click();
    cy.url().should('include', '/inventory.html');
    cy.get('.title').should('have.text', 'Products');
  });
});
